action.code:
if (!root) {
    root = new TreeNode(item);
    return;
}

if (item < root->val) {
    avlInsert(root->left, item);
} else if (item > root->val) {
    avlInsert(root->right, item);
} else {
    return;
}

int balance = height(root->left) - height(root->right);

if (balance > 1 && item < root->left->val) {
    root = rotateRight(root);
} else if (balance < -1 && item > root->right->val) {
    root = rotateLeft(root);
} else if (balance > 1 && item > root->left->val) {
    root->left = rotateLeft(root->left);
    root = rotateRight(root);
} else if (balance < -1 && item < root->right->val) {
    root->right = rotateRight(root->right);
    root = rotateLeft(root);
}
// END_CODE

